class ImportManager{constructor(t){this.listsManager=t,this.csvImporter=null,this.googleSheetsImporter=null,this.currentMethod=null,this.container=null}init(){this.container=document.getElementById("import-wizard"),this.container?(this.renderMethodSelection(),debugLog("[ImportManager] Initialized")):console.error("[ImportManager] Container #import-wizard not found")}renderMethodSelection(){this.currentMethod=null,this.container.innerHTML='\n            <div class="import-method-selection">\n                <h3 class="font-bold text-lg mb-4">Выберите способ импорта:</h3>\n\n                <div class="grid grid-cols-1 md:grid-cols-2 gap-4">\n                    \x3c!-- CSV Method Card --\x3e\n                    <div class="card bg-base-200 shadow-md hover:shadow-lg transition cursor-pointer"\n                         onclick="window.importManager.selectMethod(\'csv\')">\n                        <div class="card-body items-center text-center">\n                            <div class="text-5xl mb-2">📄</div>\n                            <h4 class="card-title">CSV файл</h4>\n                            <p class="text-sm text-base-content/70">\n                                Загрузите CSV файл с вашего компьютера\n                            </p>\n                            <div class="card-actions mt-4">\n                                <button class="btn btn-primary btn-sm">\n                                    Выбрать CSV\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n\n                    \x3c!-- Google Sheets Method Card --\x3e\n                    <div class="card bg-base-200 shadow-md hover:shadow-lg transition cursor-pointer"\n                         onclick="window.importManager.selectMethod(\'google-sheets\')">\n                        <div class="card-body items-center text-center">\n                            <div class="text-5xl mb-2">📊</div>\n                            <h4 class="card-title">Google Sheets</h4>\n                            <p class="text-sm text-base-content/70">\n                                Укажите ссылку на публичную таблицу\n                            </p>\n                            <div class="card-actions mt-4">\n                                <button class="btn btn-success btn-sm">\n                                    Использовать Google Sheets\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n\n                <div class="mt-6">\n                    <h4 class="font-bold mb-2">Общие требования к данным:</h4>\n                    <ul class="list-disc list-inside text-sm text-base-content/70 space-y-1">\n                        <li><strong>Обязательные колонки:</strong> Магазин, Группа товаров, Товар</li>\n                        <li><strong>Опциональные:</strong> Количество, Единица измерения, Комментарий</li>\n                        <li><strong>Формат:</strong> Первая строка должна содержать заголовки колонок</li>\n                    </ul>\n                </div>\n\n                <div class="mt-4">\n                    <details class="collapse collapse-arrow bg-base-100">\n                        <summary class="collapse-title text-sm font-medium">\n                            📋 Пример формата данных\n                        </summary>\n                        <div class="collapse-content">\n                            <div class="overflow-x-auto">\n                                <table class="table table-xs">\n                                    <thead>\n                                        <tr>\n                                            <th>Магазин</th>\n                                            <th>Группа товаров</th>\n                                            <th>Товар</th>\n                                            <th>Количество</th>\n                                            <th>Единица</th>\n                                            <th>Комментарий</th>\n                                        </tr>\n                                    </thead>\n                                    <tbody>\n                                        <tr>\n                                            <td>Пятёрочка</td>\n                                            <td>Молочные</td>\n                                            <td>Молоко 3.2%</td>\n                                            <td>2</td>\n                                            <td>шт</td>\n                                            <td>В красной упаковке</td>\n                                        </tr>\n                                        <tr>\n                                            <td>Пятёрочка</td>\n                                            <td>Хлеб</td>\n                                            <td>Батон белый</td>\n                                            <td>1</td>\n                                            <td>шт</td>\n                                            <td></td>\n                                        </tr>\n                                        <tr>\n                                            <td>Магнит</td>\n                                            <td>Овощи</td>\n                                            <td>Картофель</td>\n                                            <td>5</td>\n                                            <td>кг</td>\n                                            <td>Для супа</td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </div>\n                        </div>\n                    </details>\n                </div>\n            </div>\n        ',debugLog("[ImportManager] Rendered method selection")}selectMethod(t){this.currentMethod=t,debugLog("[ImportManager] Selected method:",t),"csv"===t?(this.csvImporter||"undefined"==typeof CSVImporter||(this.csvImporter=new CSVImporter(this.listsManager),window.csvImporter=this.csvImporter),this.csvImporter?(this.csvImporter.container=this.container,this.csvImporter.renderStep1()):(console.error("[ImportManager] CSVImporter not loaded"),showToast("Ошибка: CSV импортер не загружен","error"),this.renderMethodSelection())):"google-sheets"===t?(this.googleSheetsImporter||"undefined"==typeof GoogleSheetsImporter||(this.googleSheetsImporter=new GoogleSheetsImporter(this.listsManager),window.googleSheetsImporter=this.googleSheetsImporter),this.googleSheetsImporter?(this.googleSheetsImporter.container=this.container,this.googleSheetsImporter.renderStep1()):(console.error("[ImportManager] GoogleSheetsImporter not loaded"),showToast("Ошибка: Google Sheets импортер не загружен","error"),this.renderMethodSelection())):(console.error("[ImportManager] Unknown method:",t),this.renderMethodSelection())}reset(){this.renderMethodSelection(),debugLog("[ImportManager] Reset to method selection")}}window.ImportManager=ImportManager,debugLog("[ImportManager] Module loaded");